import Link from "next/link";
import {
  ArrowRight,
  Clock3,
  Hourglass,
  Mail,
  TriangleAlert,
  Users,
} from "lucide-react";
import { SEND_TIMING_DESCRIPTION } from "@/lib/email-limits";
import { cn } from "@/lib/utils";

export function HowSendingWorks({
  batchSize,
  gated,
}: {
  batchSize: number;
  gated: boolean;
}) {
  const guidance = [
    {
      title: "Batch size",
      icon: Users,
      text: `Choose up to ${batchSize} recipients per batch, within your remaining ${gated ? "daily and monthly allowances" : "24-hour allowance"}. Each person receives their own email from your Gmail.`,
    },
    {
      title: "Sending pace",
      icon: Clock3,
      text: `${SEND_TIMING_DESCRIPTION} Queue estimates include processing time; service delays can extend them. Each email gets one sending attempt.`,
    },
    {
      title: "Queue expiry",
      icon: Hourglass,
      text: "Ready sends expire after 24 hours and release unused reservations.",
    },
    {
      title: "Gmail limits",
      icon: Mail,
      text: "Gmail may apply additional limits. Sent means Gmail accepted an email, not that it reached the recipient’s inbox.",
    },
    {
      title: "Uncertain attempts",
      icon: TriangleAlert,
      text: `${gated ? "Attempts count in the period when sending is claimed. Uncertain attempts stay charged." : "Uncertain attempts retain capacity."} They are never automatically resent. Check Gmail Sent and review History before trying again.`,
      warning: true,
    },
  ];
  return (
    <section
      aria-labelledby="sending-guidance"
      className="usage-guidance mt-14"
    >
      <h2
        id="sending-guidance"
        className="text-[clamp(22px,3vw,28px)] font-extrabold tracking-[-0.03em] workspace-mono:font-bold"
      >
        How sending works
      </h2>
      <div
        className={`usage-guidance-grid grid grid-cols-[repeat(2,_minmax(0,_1fr))] gap-4 mt-5 [@media(max-width:_820px)]:grid-cols-1`}
      >
        {guidance.map(({ title, icon: Icon, text, warning }) => (
          <article
            key={title}
            className={cn(
              "hover-card",
              "backdrop-blur-xs workspace-mono:backdrop-blur-none [background:var(--usage-card)] border border-solid border-[var(--usage-line)] p-5.5 rounded-[var(--appearance-radius,_20px)]",
              warning &&
                "[grid-column:1_/_-1] border-[color-mix(in_srgb,_var(--usage-yellow)_45%,_transparent)] workspace-mono:border-[var(--usage-warning-line)]",
            )}
          >
            <h3 className="text-[16px] font-bold tracking-[-0.01em] flex gap-2.5 items-center">
              <span
                className={cn(
                  "w-7.5 h-7.5 flex-none rounded-[var(--appearance-radius,9px)] grid place-items-center workspace-mono:rounded-[var(--usage-button-radius)]",
                  warning
                    ? "text-[var(--usage-yellow)] [background:color-mix(in_srgb,var(--usage-yellow)_16%,transparent)] workspace-mono:bg-[var(--usage-warning-bg)]"
                    : "[background:var(--appearance-wash,var(--color-usage-background-27))] text-[var(--usage-accent)] workspace-mono:bg-[var(--usage-inset)] workspace-mono:text-[var(--usage-text)]",
                )}
              >
                <Icon size={17} aria-hidden="true" />
              </span>
              {title}
            </h3>
            <p className="text-[var(--usage-muted)] text-[14px] mt-2.5">
              {text}
            </p>
          </article>
        ))}
      </div>
      <Link
        href="/history"
        className={`inline-flex items-center min-h-11 mt-6 gap-2 text-[14.5px] font-bold button-interaction`}
      >
        Review email history <ArrowRight size={16} aria-hidden="true" />
      </Link>
    </section>
  );
}
